/// <summary>
/// AVA <c>initJournalLine</c>
/// </summary>
/// <param name = "_parmLine">Common</param>
/// <returns>Common</returns>
public Common initJournalLine(Common _parmLine)
{
    VendPackingSlipTrans    vendPackingSlipTransLoc = next initJournalLine(_parmLine);
    PurchLine               purchLine               = vendPackingSlipTransLoc.purchLine();

    if(purchLine.AVAGRUpdate
        && !vendPackingSlipJour.isProForma())
    {
        purchLine.avaUpdatePurchLineMarkup();
    }

    return vendPackingSlipTransLoc;
}
